"use client";

import { useId } from "react";
import Link from "next/link";
import {
  ArrowUpRight,
  CalendarDays,
  Check,
  CreditCard,
  FlaskConical,
  ReceiptText,
  ShieldCheck,
  Sparkles,
} from "lucide-react";
import type {
  CommerceBilling as Billing,
  CommerceContextValue,
} from "@/lib/commerce";
import { commercePlans } from "@/lib/commerce-state";
import { cn } from "@/lib/utils";
import { CommerceInvoiceTable } from "@/components/blocks/commerce-invoice-view";
import {
  CommerceStatusBadge,
  useCommerceFormatting,
  type CommerceTask,
} from "@/components/blocks/commerce-checkout";
import { Alert } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button, buttonVariants } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Empty } from "@/components/ui/empty";

export function CommerceBilling({
  commerce,
  task,
  onPlan,
  onPortal,
}: {
  commerce: CommerceContextValue;
  task: CommerceTask;
  onPlan: (plan: Billing["plan"]) => void;
  onPortal: () => void;
}) {
  const { l, locale, money, date, number } = useCommerceFormatting();
  const headingId = useId();
  const { billing } = commerce;
  const mock = commerce.mode === "mock";
  const disabled = task.disabled || !commerce.canManageBilling;
  const history = [...commerce.invoices]
    .sort((a, b) => b.issuedAt.localeCompare(a.issuedAt))
    .slice(0, 6);
  const periodLabel =
    billing.status === "trialing"
      ? l("Trial ends", "Fin de la prueba")
      : billing.status === "active"
        ? l("Next renewal", "Próxima renovación")
        : l("Billing period ends", "Fin del período de facturación");

  return (
    <section aria-labelledby={headingId} className="grid min-w-0 gap-6">
      <div
        data-motion="intro"
        className="flex min-w-0 flex-col justify-between gap-5 sm:flex-row sm:items-end"
      >
        <div className="min-w-0">
          <p className="mb-3 flex items-center gap-2 text-[11px] leading-5 font-semibold tracking-[.1em] text-primary uppercase">
            <span
              aria-hidden="true"
              className="h-px w-5 shrink-0 bg-primary/65"
            />
            {l("Room to grow", "Espacio para crecer")}
          </p>
          <h2
            id={headingId}
            className="text-[30px] leading-[1.15] font-semibold tracking-[-.035em] text-balance sm:text-[36px]"
          >
            {l("Plans & billing", "Planes y facturación")}
          </h2>
          <p className="mt-3 max-w-2xl text-[14px] leading-7 text-pretty text-muted-foreground">
            {l(
              "Your subscription, payment method and workspace invoice history.",
              "Tu suscripción, método de pago e historial de facturas del workspace.",
            )}
          </p>
        </div>
        <div className="flex shrink-0 flex-wrap items-center gap-2 sm:pb-1">
          <Button
            type="button"
            variant="outline"
            disabled={disabled}
            loading={task.pending}
            onClick={onPortal}
          >
            <CreditCard aria-hidden="true" />
            {mock
              ? l("Preview portal", "Ver portal de ejemplo")
              : l("Manage billing", "Gestionar facturación")}
            {!mock && <ArrowUpRight aria-hidden="true" />}
          </Button>
        </div>
      </div>
      {billing.status === "past_due" && (
        <Alert
          variant="warning"
          title={l(
            "Subscription needs attention",
            "La suscripción necesita atención",
          )}
        >
          {l(
            "Review your billing details and outstanding invoices to resolve the overdue payment.",
            "Revisa tus datos de facturación y las facturas pendientes para resolver el pago vencido.",
          )}
        </Alert>
      )}
      {billing.status === "cancelled" && (
        <Alert title={l("Subscription cancelled", "Suscripción cancelada")}>
          {l(
            "The recorded subscription is cancelled. Review a plan to start a new checkout.",
            "La suscripción registrada está cancelada. Revisa un plan para iniciar un nuevo pago.",
          )}
        </Alert>
      )}
      <div className="grid gap-5 lg:grid-cols-[minmax(0,1.3fr)_minmax(0,1fr)]">
        <Card appearance="gradient" className="overflow-hidden">
          <CardHeader className="border-b border-border/65">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <CardTitle>{l("Your current plan", "Tu plan actual")}</CardTitle>
              <CommerceStatusBadge status={billing.status} />
            </div>
            <CardDescription>
              {l(
                "A clear view of your current subscription.",
                "Una vista clara de tu suscripción actual.",
              )}
            </CardDescription>
          </CardHeader>
          <CardContent className="pt-6">
            <div className="flex flex-wrap items-start justify-between gap-5">
              <div>
                <div className="flex items-center gap-2.5">
                  <Sparkles
                    aria-hidden="true"
                    className="size-5 text-primary"
                  />
                  <h2 className="text-2xl font-semibold tracking-tight">
                    {billing.plan}
                  </h2>
                </div>
                <p className="mt-5 text-3xl font-semibold tracking-tight tabular-nums">
                  {money(billing.amount, billing.currency)}
                  <span className="ml-2 text-xs font-normal tracking-normal text-muted-foreground">
                    {billing.interval === "month"
                      ? l("/ month", "/ mes")
                      : l("/ year", "/ año")}
                  </span>
                </p>
              </div>
              <Badge variant="outline">
                {mock
                  ? l("Demo subscription", "Suscripción de ejemplo")
                  : l("Service subscription", "Suscripción del servicio")}
              </Badge>
            </div>
            <div className="mt-6 flex flex-wrap items-center gap-2.5 rounded-xl border border-border bg-surface/60 px-4 py-3 text-xs">
              <CalendarDays
                aria-hidden="true"
                className="size-4 text-primary"
              />
              <span className="text-muted-foreground">{periodLabel}</span>
              <span className="ml-auto font-semibold">
                {date(billing.currentPeriodEnd)}
              </span>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader>
            <CardTitle>{l("Payment method", "Método de pago")}</CardTitle>
            <CardDescription>
              {l(
                "Only the recorded brand and last four digits are shown.",
                "Se muestran la marca y los últimos cuatro dígitos registrados.",
              )}
            </CardDescription>
          </CardHeader>
          <CardContent className="grid gap-5">
            <div className="flex items-center gap-4 rounded-xl border border-border bg-surface-subtle/40 p-4">
              <span
                aria-hidden="true"
                className="flex h-10 w-14 shrink-0 items-center justify-center rounded-lg border border-border bg-surface"
              >
                <CreditCard className="size-5 text-primary" />
              </span>
              <div className="min-w-0">
                <p className="text-sm font-semibold">
                  {billing.cardBrand} · •••• {billing.cardLast4}
                </p>
                <p className="mt-1 text-[11px] text-muted-foreground">
                  {mock
                    ? l(
                        "Masked demo payment method",
                        "Método de pago de ejemplo enmascarado",
                      )
                    : l("Saved payment method", "Método de pago guardado")}
                </p>
              </div>
            </div>
            <div>
              <p className="text-[11px] text-muted-foreground">
                {l("Billing email", "Correo de facturación")}
              </p>
              <p className="mt-1 break-all text-xs font-medium">
                {billing.customerEmail}
              </p>
            </div>
            <Button
              type="button"
              variant="outline"
              disabled={disabled}
              onClick={onPortal}
            >
              <ShieldCheck aria-hidden="true" />
              {mock
                ? l("Review demo billing", "Revisar facturación de ejemplo")
                : l("Open customer portal", "Abrir portal de cliente")}
            </Button>
          </CardContent>
        </Card>
      </div>

      <section
        aria-label={l("Available plans", "Planes disponibles")}
        className="grid gap-4 md:grid-cols-3"
      >
        {commercePlans.map((plan) => {
          const current = billing.plan === plan.name;
          const settled = current && billing.status === "active";
          return (
            <Card
              key={plan.name}
              className={cn(
                "flex flex-col p-5 sm:p-6",
                current && "border-primary/45",
              )}
            >
              <div className="flex min-w-0 flex-wrap items-center justify-between gap-2">
                <h2 className="text-base font-semibold">{plan.name}</h2>
                {current && <Badge>{l("Current plan", "Plan actual")}</Badge>}
              </div>
              <p className="mt-6 text-2xl font-semibold tracking-tight tabular-nums">
                {mock
                  ? money(plan.amount, billing.currency)
                  : l("Price at checkout", "Precio al pagar")}
              </p>
              <p className="mt-2 text-[11px] leading-5 text-muted-foreground">
                {mock
                  ? l(
                      "Illustrative monthly price",
                      "Precio mensual ilustrativo",
                    )
                  : l(
                      "Your service confirms pricing and terms.",
                      "Tu servicio confirma los precios y las condiciones.",
                    )}
              </p>
              <p className="my-5 flex-1 text-xs leading-6 text-muted-foreground">
                {plan.name === "Starter"
                  ? l(
                      "A considered start for a small workspace.",
                      "Un comienzo cuidado para un workspace pequeño.",
                    )
                  : plan.name === "Pro"
                    ? l(
                        "More room for a growing team.",
                        "Más espacio para un equipo en crecimiento.",
                      )
                    : l(
                        "A plan for a shared ambition.",
                        "Un plan para una ambición compartida.",
                      )}
              </p>
              <Button
                type="button"
                variant={
                  current
                    ? "secondary"
                    : plan.name === "Enterprise"
                      ? "default"
                      : "outline"
                }
                className="w-full"
                disabled={disabled || settled}
                onClick={() => onPlan(plan.name)}
              >
                {settled ? (
                  <Check aria-hidden="true" />
                ) : (
                  <ArrowUpRight aria-hidden="true" />
                )}
                {settled
                  ? l("Current plan", "Plan actual")
                  : mock
                    ? l(`Preview ${plan.name}`, `Ver ${plan.name}`)
                    : l(`Review ${plan.name}`, `Revisar ${plan.name}`)}
              </Button>
            </Card>
          );
        })}
      </section>
      <div className="flex items-start gap-3 rounded-xl border border-border bg-surface-subtle/30 px-4 py-3 text-xs leading-6 text-muted-foreground">
        {mock ? (
          <FlaskConical
            aria-hidden="true"
            className="mt-1 size-4 shrink-0 text-primary"
          />
        ) : (
          <ShieldCheck
            aria-hidden="true"
            className="mt-1 size-4 shrink-0 text-primary"
          />
        )}
        <p>
          {mock
            ? l(
                "Plan previews use mock payments. A successful simulation updates the shared subscription and adds its invoice below.",
                "Las vistas previas de planes usan pagos simulados. Una simulación exitosa actualiza la suscripción compartida y agrega su factura abajo.",
              )
            : l(
                "Plan changes and the customer portal open through your commerce service. The service confirms the resulting subscription.",
                "Los cambios de plan y el portal de cliente se abren mediante tu servicio de comercio. El servicio confirma la suscripción resultante.",
              )}
        </p>
      </div>
      <Card className="overflow-hidden">
        <CardHeader className="border-b border-border/65">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div>
              <CardTitle>
                {l("Invoice history", "Historial de facturas")}
              </CardTitle>
              <CardDescription className="mt-1">
                {l(
                  "Order receipts and workspace invoices in one place.",
                  "Recibos de pedidos y facturas del workspace en un solo lugar.",
                )}
              </CardDescription>
            </div>
            <Link
              href={`/${locale}/invoices/`}
              className={buttonVariants({ variant: "outline", size: "sm" })}
            >
              {l("All invoices", "Todas las facturas")}
              <ArrowUpRight aria-hidden="true" />
            </Link>
          </div>
        </CardHeader>
        {history.length ? (
          <CommerceInvoiceTable invoices={history} />
        ) : (
          <Empty
            icon={<ReceiptText aria-hidden="true" className="size-5" />}
            title={l(
              "No invoice history yet",
              "Aún no hay historial de facturas",
            )}
            description={
              mock
                ? l(
                    "Created invoices and successful demo checkout receipts appear here.",
                    "Aquí aparecen las facturas creadas y los recibos de pagos de ejemplo exitosos.",
                  )
                : l(
                    "Invoices from your commerce service appear here.",
                    "Aquí aparecen las facturas de tu servicio de comercio.",
                  )
            }
          />
        )}
        {history.length > 0 && (
          <p className="border-t border-border px-5 py-3 text-[11px] text-muted-foreground">
            {l(
              `Showing ${number(history.length)} of ${number(commerce.invoices.length)} workspace invoices.`,
              `Mostrando ${number(history.length)} de ${number(commerce.invoices.length)} facturas del workspace.`,
            )}
          </p>
        )}
      </Card>
    </section>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import Link from "next/link";
import {
  ArrowUpRight,
  CheckCircle2,
  CreditCard,
  FlaskConical,
  Package,
  ReceiptText,
  RotateCcw,
  ShieldCheck,
} from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import {
  CommerceError,
  type CommerceAction,
  type CommerceContextValue,
  type CommerceCurrency,
} from "@/lib/commerce";
import { commercePlans } from "@/lib/commerce-state";
import { publicPath } from "@/lib/public-path";
import { cn } from "@/lib/utils";
import { Alert } from "@/components/ui/alert";
import { Badge, type BadgeProps } from "@/components/ui/badge";
import { Button, buttonVariants } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogTitle,
} from "@/components/ui/dialog";

export type MockCommerceAction = Extract<CommerceAction, { mode: "mock" }>;
export type CommerceTask = {
  pending: boolean;
  disabled: boolean;
  error: string | null;
  clearError: () => void;
  run: <T>(
    operation: () => Promise<T>,
    onSuccess?: (value: T) => void,
  ) => Promise<boolean>;
};

export function commerceErrorMessage(
  cause: unknown,
  l: (en: string, es: string) => string,
) {
  if (cause instanceof CommerceError) {
    const messages: Record<CommerceError["code"], string> = {
      validation: l(
        "Check the details and try again.",
        "Revisa los datos e intenta de nuevo.",
      ),
      unavailable: l(
        "This record or product is no longer available. Refresh and try again.",
        "Este registro o producto ya no está disponible. Actualiza e intenta de nuevo.",
      ),
      conflict: l(
        "The record could not be changed in its current state. Refresh and review its availability or status.",
        "No se pudo cambiar el registro en su estado actual. Actualiza y revisa su disponibilidad o estado.",
      ),
      forbidden: l(
        "Your current role cannot make this change.",
        "Tu rol actual no permite realizar este cambio.",
      ),
      provider: l(
        "The commerce service could not complete this request. Try again.",
        "El servicio de comercio no pudo completar la solicitud. Intenta de nuevo.",
      ),
    };
    return l(cause.message || messages[cause.code], messages[cause.code]);
  }
  return l(
    "The request could not be completed. Your details are still here; try again.",
    "No se pudo completar la solicitud. Tus datos siguen aquí; intenta de nuevo.",
  );
}

/** One request at a time; late responses cannot reopen an unmounted workspace. */
export function useCommerceTask(commerce: CommerceContextValue): CommerceTask {
  const { l } = useLanguage();
  const mounted = useRef(false);
  const inFlight = useRef(false);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  const run = useCallback(
    async <T,>(
      operation: () => Promise<T>,
      onSuccess?: (value: T) => void,
    ): Promise<boolean> => {
      if (!mounted.current || inFlight.current || commerce.busy !== null) {
        return false;
      }
      inFlight.current = true;
      setPending(true);
      setError(null);
      try {
        const result = await operation();
        if (!mounted.current) return false;
        onSuccess?.(result);
        return true;
      } catch (cause) {
        if (mounted.current) setError(commerceErrorMessage(cause, l));
        return false;
      } finally {
        inFlight.current = false;
        if (mounted.current) setPending(false);
      }
    },
    [commerce.busy, l],
  );

  const clearError = useCallback(() => setError(null), []);
  return {
    pending,
    disabled: pending || commerce.busy !== null || !commerce.ready,
    error,
    clearError,
    run,
  };
}

export function useCommerceFormatting() {
  const language = useLanguage();
  const { number } = language;
  const money = useCallback(
    (amount: number, currency: CommerceCurrency) =>
      number(amount / 100, {
        style: "currency",
        currency: currency.toUpperCase(),
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      }),
    [number],
  );
  return { ...language, money };
}

type CommerceStatus =
  | CommerceContextValue["orders"][number]["status"]
  | CommerceContextValue["orders"][number]["paymentStatus"]
  | CommerceContextValue["invoices"][number]["status"]
  | CommerceContextValue["billing"]["status"];

export function CommerceStatusBadge({ status }: { status: CommerceStatus }) {
  const { l } = useLanguage();
  const labels: Record<CommerceStatus, string> = {
    processing: l("Processing", "En preparación"),
    shipped: l("Shipped", "Enviado"),
    delivered: l("Delivered", "Entregado"),
    cancelled: l("Cancelled", "Cancelado"),
    unpaid: l("Unpaid", "Sin pagar"),
    paid: l("Paid", "Pagado"),
    failed: l("Failed", "Fallido"),
    refunded: l("Refunded", "Reembolsado"),
    draft: l("Draft", "Borrador"),
    open: l("Open", "Pendiente"),
    overdue: l("Overdue", "Vencido"),
    void: l("Void", "Anulado"),
    active: l("Active", "Activo"),
    trialing: l("Trial", "Prueba"),
    past_due: l("Past due", "Pago vencido"),
  };
  const variant: BadgeProps["variant"] = [
    "failed",
    "overdue",
    "past_due",
  ].includes(status)
    ? "destructive"
    : ["processing", "unpaid", "trialing", "open"].includes(status)
      ? "warning"
      : ["draft", "cancelled", "refunded", "void"].includes(status)
        ? "neutral"
        : "default";
  return <Badge variant={variant}>{labels[status]}</Badge>;
}

export function CommerceTotals({
  amounts,
}: {
  amounts: readonly { amount: number; currency: CommerceCurrency }[];
}) {
  const { l, money } = useCommerceFormatting();
  const totals = new Map<CommerceCurrency, number>();
  for (const item of amounts) {
    totals.set(item.currency, (totals.get(item.currency) ?? 0) + item.amount);
  }
  return totals.size ? (
    <span className="flex flex-col gap-1 tabular-nums">
      {[...totals]
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([currency, amount]) => (
          <span key={currency}>{money(amount, currency)}</span>
        ))}
    </span>
  ) : (
    <span className="text-muted-foreground">{l("—", "—")}</span>
  );
}

export function CommerceProductThumbnail({
  src,
  className,
}: {
  src?: string;
  className?: string;
}) {
  return (
    <span
      className={cn(
        "flex size-12 shrink-0 items-center justify-center overflow-hidden rounded-lg border border-border bg-surface-subtle",
        className,
      )}
    >
      {src ? (
        <img
          src={publicPath(src)}
          alt=""
          loading="lazy"
          className="size-full object-cover"
        />
      ) : (
        <Package aria-hidden="true" className="size-5 text-muted-foreground" />
      )}
    </span>
  );
}

export function CommerceCheckout({
  action,
  commerce,
  task,
  onClose,
}: {
  action: MockCommerceAction;
  commerce: CommerceContextValue;
  task: CommerceTask;
  onClose: () => void;
}) {
  const { l, locale, money, date } = useCommerceFormatting();
  const [outcome, setOutcome] = useState<"preview" | "paid" | "failed">(
    "preview",
  );
  const order =
    action.kind === "order"
      ? commerce.orders.find((item) => item.id === action.id)
      : undefined;
  const invoice =
    action.kind === "invoice"
      ? commerce.invoices.find((item) => item.id === action.id)
      : undefined;
  const plan =
    action.kind === "subscription"
      ? commercePlans.find((item) => item.name === action.id)
      : undefined;
  const portal = action.kind === "portal";
  const valid = portal || !!order || !!invoice || !!plan;
  const allowed =
    portal || plan ? commerce.canManageBilling : commerce.canWrite;
  const paid =
    outcome === "paid" ||
    order?.paymentStatus === "paid" ||
    invoice?.status === "paid";
  const payable =
    valid &&
    !portal &&
    !paid &&
    order?.status !== "cancelled" &&
    order?.paymentStatus !== "refunded" &&
    invoice?.status !== "draft" &&
    invoice?.status !== "void";
  const stockQuantities = new Map<string, number>();
  for (const line of order?.items ?? []) {
    stockQuantities.set(
      line.productId,
      (stockQuantities.get(line.productId) ?? 0) + line.quantity,
    );
  }
  const stockProblem = [...stockQuantities].some(([productId, quantity]) => {
    const product = commerce.products.find((item) => item.id === productId);
    return (
      !product || product.status !== "active" || product.inventory < quantity
    );
  });
  const amount = order?.total ?? invoice?.amount ?? plan?.amount;
  const currency =
    order?.currency ?? invoice?.currency ?? commerce.billing.currency;
  const label = order?.number ?? invoice?.number ?? plan?.name;
  const customer =
    order?.customerEmail ??
    invoice?.customerEmail ??
    commerce.billing.customerEmail;
  const receipt = order
    ? commerce.invoices.find((item) => item.id === `inv-order-${order.id}`)
    : undefined;
  const title = portal
    ? l("Demo customer portal", "Portal de cliente de ejemplo")
    : paid
      ? l("Demo payment complete", "Pago de ejemplo completado")
      : l("Preview demo checkout", "Vista previa del pago de ejemplo");

  const simulate = (next: "paid" | "failed") => {
    if (task.disabled || !allowed || !payable || commerce.mode !== "mock")
      return;
    void task.run(
      () => commerce.simulateCheckout(action, next),
      () => setOutcome(next),
    );
  };

  return (
    <Dialog
      open
      onOpenChange={(open) => {
        if (!open && !task.pending && commerce.busy === null) onClose();
      }}
    >
      <DialogContent
        closeLabel={l("Close preview", "Cerrar vista previa")}
        className="max-w-xl"
      >
        <Badge variant="outline" className="mb-4">
          <FlaskConical aria-hidden="true" />
          {l("Mock · no charge", "Simulación · sin cobro")}
        </Badge>
        <DialogTitle>{title}</DialogTitle>
        <DialogDescription>
          {portal
            ? l(
                "Review the subscription stored in this demo workspace.",
                "Consulta la suscripción guardada en este workspace de ejemplo.",
              )
            : l(
                "Choose a simulated result. No card details are needed and no money moves.",
                "Elige un resultado simulado. No se necesitan datos de tarjeta y no se mueve dinero.",
              )}
        </DialogDescription>

        <div className="mt-6 grid gap-5">
          {!valid ? (
            <Alert
              variant="warning"
              title={l("Record unavailable", "Registro no disponible")}
            >
              {l(
                "Close this preview and refresh the workspace.",
                "Cierra esta vista previa y actualiza el workspace.",
              )}
            </Alert>
          ) : portal ? (
            <>
              <div className="rounded-xl border border-border bg-surface-subtle/40 p-5">
