        l("Use a positive amount.", "Usa un importe positivo."),
      ),
    status: z.string(),
    stock: z.number().int().min(0).optional(),
  });
  type Values = z.infer<typeof schema>;
  const form = useForm<Values>({
    resolver: zodResolver(schema),
    defaultValues: {
      name: "",
      detail: "",
      category: "",
      amount: 0,
      status: statuses[0],
