export class CommerceError extends Error {
  readonly code:
    "validation" | "unavailable" | "conflict" | "forbidden" | "provider";
  constructor(code: CommerceError["code"], message: string) {
    super(message);
    this.name = "CommerceError";
    this.code = code;
  }
}

export function buildOrder(
  input: NewOrderInput,
  products: readonly CommerceProduct[],
  id: string,
  createdAt: string,
): CommerceOrder {
  const result = newOrderSchema.safeParse(input);
  if (!result.success)
    throw new CommerceError("validation", "Check the order fields.");
  const merged = new Map<string, number>();
  for (const line of result.data.items) {
    merged.set(
      line.productId,
      (merged.get(line.productId) ?? 0) + line.quantity,
    );
  }
  let orderCurrency: CommerceCurrency | undefined;
  const items = [...merged].map(([productId, quantity]) => {
    const product = products.find((item) => item.id === productId);
    if (!product || product.status !== "active") {
      throw new CommerceError(
        "unavailable",
        "The selected product is unavailable.",
      );
    }
    if (quantity > 999 || quantity > product.inventory) {
      throw new CommerceError("conflict", "There is not enough inventory.");
    }
    if (orderCurrency && orderCurrency !== product.currency) {
      throw new CommerceError("validation", "Use one currency per order.");
    }
    orderCurrency = product.currency;
    return {
      productId,
      name: product.name,
      quantity,
      unitAmount: product.unitAmount,
      ...(product.images[0] ? { image: product.images[0].src } : {}),
    };
  });
  const order: CommerceOrder = {
    id,
    number: `#${id.replace(/^ord-/, "").slice(0, 12).toUpperCase()}`,
    customerName: result.data.customerName,
    customerEmail: result.data.customerEmail,
    currency: orderCurrency ?? "usd",
    total: items.reduce(
      (sum, item) => sum + item.unitAmount * item.quantity,
      0,
    ),
    status: "processing",
    paymentStatus: "unpaid",
    items,
    createdAt,
    shippingAddress: result.data.shippingAddress ?? "",
  };
  const validated = commerceOrderSchema.safeParse(order);
  if (!validated.success)
    throw new CommerceError("validation", "The order total is out of range.");
  return validated.data;
}

import type {
  ColumnFiltersState,
  ColumnOrderState,
  ColumnPinningState,
  ColumnSizingState,
  PaginationState,
  SortingState,
  VisibilityState,
} from "@tanstack/react-table";

/** Serializable table state. Filtering, sorting and pagination belong to the data owner in external mode. */
export type DataTableQuery = {
  search: string;
  filters: ColumnFiltersState;
  sorting: SortingState;
  pagination: PaginationState;
};

/** Separate from DataTable's existing `columnVisibility` menu flag. */
export type DataTableColumnState = {
  visibility: VisibilityState;
  order: ColumnOrderState;
  sizing: ColumnSizingState;
  pinning: ColumnPinningState;
};

export type DataFilterScalar = string | number | boolean | null;
export type DataFilter =
  | { operator: "contains" | "startsWith"; value: string }
  | { operator: "equals" | "notEquals"; value: DataFilterScalar }
  | { operator: "in" | "notIn"; value: DataFilterScalar[] }
  | { operator: "gt" | "gte" | "lt" | "lte"; value: number }
  | { operator: "between"; value: [number | null, number | null] }
  | { operator: "dateBetween"; value: [string | null, string | null] }
  | { operator: "isEmpty" | "isNotEmpty" };

type JsonValue = DataFilterScalar | JsonValue[] | { [key: string]: JsonValue };

export type DataQueryNormalizationOptions = {
  pageSize?: number;
  maxPageSize?: number;
  columnIds?: readonly string[];
};

function record(value: unknown): Record<string, unknown> | undefined {
  if (
    !value ||
    typeof value !== "object" ||
    Array.isArray(value) ||
    (Object.getPrototypeOf(value) !== Object.prototype &&
      Object.getPrototypeOf(value) !== null)
  ) {
    return undefined;
  }
  return value as Record<string, unknown>;
}

function jsonValue(value: unknown, depth = 0): JsonValue | undefined {
  if (depth > 12) return undefined;
  if (
    value === null ||
    typeof value === "string" ||
    typeof value === "boolean"
  ) {
    return value;
  }
  if (typeof value === "number")
    return Number.isFinite(value) ? value : undefined;
  if (Array.isArray(value)) {
    const values = value.map((item) => jsonValue(item, depth + 1));
    return values.some((item) => item === undefined)
      ? undefined
      : (values as JsonValue[]);
  }
  const object = record(value);
  if (!object) return undefined;
  const entries = Object.keys(object)
    .sort()
    .map((key) => [key, jsonValue(object[key], depth + 1)] as const);
  return entries.some(([, item]) => item === undefined)
    ? undefined
    : (Object.fromEntries(entries) as { [key: string]: JsonValue });
}

function integer(
  value: unknown,
  fallback: number,
  minimum: number,
  maximum = Number.MAX_SAFE_INTEGER,
) {
  const number =
    typeof value === "number"
      ? value
      : typeof value === "string" && value.trim()
        ? Number(value)
        : NaN;
  return Number.isFinite(number)
    ? Math.min(maximum, Math.max(minimum, Math.trunc(number)))
    : fallback;
}

function scalar(value: unknown): value is DataFilterScalar {
  return (
    value === null ||
    typeof value === "string" ||
    typeof value === "boolean" ||
    (typeof value === "number" && Number.isFinite(value))
  );
}

function dateDay(value: unknown): number | undefined {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value))
    return undefined;
  const timestamp = Date.parse(`${value}T00:00:00.000Z`);
  return Number.isFinite(timestamp) &&
    new Date(timestamp).toISOString().slice(0, 10) === value
    ? timestamp
    : undefined;
}

export function isDataFilter(value: unknown): value is DataFilter {
  const filter = record(value);
  if (!filter) return false;
  switch (filter.operator) {
    case "contains":
    case "startsWith":
      return typeof filter.value === "string";
    case "equals":
    case "notEquals":
      return scalar(filter.value);
    case "in":
    case "notIn":
      return Array.isArray(filter.value) && filter.value.every(scalar);
    case "gt":
    case "gte":
    case "lt":
    case "lte":
      return typeof filter.value === "number" && Number.isFinite(filter.value);
    case "between":
      return (
        Array.isArray(filter.value) &&
        filter.value.length === 2 &&
        filter.value.every(
          (bound) =>
            bound === null ||
            (typeof bound === "number" && Number.isFinite(bound)),
        )
      );
    case "dateBetween":
      return (
        Array.isArray(filter.value) &&
        filter.value.length === 2 &&
        filter.value.every(
          (bound) => bound === null || dateDay(bound) !== undefined,
        )
      );
    case "isEmpty":
    case "isNotEmpty":
      return true;
    default:
      return false;
  }
}

function emptyFilter(value: unknown) {
  if (value === undefined || value === "") return true;
  if (!isDataFilter(value)) return Array.isArray(value) && value.length === 0;
  if (value.operator === "contains" || value.operator === "startsWith")
    return value.value === "";
  if (value.operator === "in" || value.operator === "notIn")
    return value.value.length === 0;
  if (value.operator === "between" || value.operator === "dateBetween") {
    return value.value.every((bound) => bound === null);
  }
  return false;
}

export function normalizeDataTableQuery(
  value: unknown = {},
  options: DataQueryNormalizationOptions = {},
): DataTableQuery {
  const input = record(value) ?? {};
  const allowed = options.columnIds ? new Set(options.columnIds) : undefined;
  const id = (value: unknown) =>
    typeof value === "string" &&
    value.trim() &&
    (!allowed || allowed.has(value))
      ? value
      : undefined;
  const filters = new Map<string, JsonValue>();
  for (const item of Array.isArray(input.filters) ? input.filters : []) {
    const filter = record(item),
      columnId = id(filter?.id);
    if (!filter || !columnId) continue;
    const normalized = jsonValue(filter.value);
    if (
      emptyFilter(normalized) ||
      (record(normalized)?.operator !== undefined && !isDataFilter(normalized))
    ) {
      filters.delete(columnId);
    } else if (normalized !== undefined) {
      filters.set(columnId, normalized);
    }
  }
  const sorting = new Map<string, { id: string; desc: boolean }>();
  for (const item of Array.isArray(input.sorting) ? input.sorting : []) {
    const sort = record(item),
      columnId = id(sort?.id);
    if (columnId)
      sorting.set(columnId, { id: columnId, desc: sort?.desc === true });
  }
  const pagination = record(input.pagination) ?? {};
  const maximum = integer(options.maxPageSize, Number.MAX_SAFE_INTEGER, 1);
  const fallbackSize = integer(options.pageSize, 5, 1, maximum);
  return {
    // Preserve spaces while typing. Trimming controlled input state loses word separators.
    search: typeof input.search === "string" ? input.search : "",
    filters: [...filters]
      .sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0))
      .map(([id, value]) => ({ id, value })),
    // Multi-sort precedence is ordered, unlike AND filters.
    sorting: [...sorting.values()],
    pagination: {
      pageIndex: integer(pagination.pageIndex, 0, 0),
      pageSize: integer(pagination.pageSize, fallbackSize, 1, maximum),
    },
  };
}

export function serializeDataTableQuery(query: DataTableQuery): string {
  return JSON.stringify({ version: 1, query: normalizeDataTableQuery(query) });
}

export function parseDataTableQuery(
  source: string | null | undefined,
  options: DataQueryNormalizationOptions = {},
): DataTableQuery {
  if (!source) return normalizeDataTableQuery({}, options);
  try {
    const input = record(JSON.parse(source));
    return input?.version === 1
      ? normalizeDataTableQuery(input.query, options)
      : normalizeDataTableQuery({}, options);
  } catch {
    return normalizeDataTableQuery({}, options);
  }
}

export function normalizeDataTableColumnState(
  value: Partial<DataTableColumnState> | unknown = {},
): DataTableColumnState {
  const input = record(value) ?? {};
  const visibility = record(input.visibility) ?? {},
    sizing = record(input.sizing) ?? {};
  const ids = (value: unknown) => [
    ...new Set(
      (Array.isArray(value) ? value : []).filter(
        (id): id is string => typeof id === "string" && id.trim().length > 0,
      ),
    ),
  ];
  const pinning = record(input.pinning) ?? {},
    left = ids(pinning.left);
  return {
    visibility: Object.fromEntries(
      Object.entries(visibility)
        .filter(([, visible]) => typeof visible === "boolean")
        .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)),
    ) as VisibilityState,
    order: ids(input.order),
    sizing: Object.fromEntries(
      Object.entries(sizing)
        .filter(
          ([, size]) =>
            typeof size === "number" && Number.isFinite(size) && size > 0,
        )
        .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)),
    ) as ColumnSizingState,
    pinning: {
      left,
      right: ids(pinning.right).filter((id) => !left.includes(id)),
    },
  };
}

function fold(value: unknown) {
  return String(value ?? "")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
}

function numeric(value: unknown): number | undefined {
  if (typeof value === "number")
    return Number.isFinite(value) ? value : undefined;
  if (typeof value !== "string" || !value.trim()) return undefined;
  const number = Number(value);
  return Number.isFinite(number) ? number : undefined;
}

/** AND across columns; `in` is OR within one field. No implicit conversion of empty cells to zero. */
export function matchesDataFilter(value: unknown, filter: unknown): boolean {
  if (emptyFilter(filter)) return true;
  if (!isDataFilter(filter)) {
    if (Array.isArray(filter))
      return filter.some((item) => Object.is(item, value));
    return typeof filter === "string"
      ? fold(value).includes(fold(filter))
      : Object.is(value, filter);
  }
  switch (filter.operator) {
    case "contains":
      return fold(value).includes(fold(filter.value));
    case "startsWith":
      return fold(value).startsWith(fold(filter.value));
    case "equals":
      return Object.is(value, filter.value);
    case "notEquals":
      return !Object.is(value, filter.value);
    case "in":
      return filter.value.some((item) => Object.is(item, value));
    case "notIn":
      return !filter.value.some((item) => Object.is(item, value));
    case "isEmpty":
      return (
        value === null ||
        value === undefined ||
        value === "" ||
        (Array.isArray(value) && value.length === 0)
      );
    case "isNotEmpty":
      return (
        value !== null &&
        value !== undefined &&
        value !== "" &&
        (!Array.isArray(value) || value.length > 0)
      );
    case "dateBetween": {
      const timestamp =
        value instanceof Date
          ? value.getTime()
          : typeof value === "string"
            ? value.length === 10
              ? (dateDay(value) ?? NaN)
              : Date.parse(value)
            : NaN;
      const [from, to] = filter.value;
      return (
        Number.isFinite(timestamp) &&
        (from === null || timestamp >= dateDay(from)!) &&
        (to === null || timestamp < dateDay(to)! + 86_400_000)
      );
    }
    default: {
      const number = numeric(value);
      if (number === undefined) return false;
      if (filter.operator === "between") {
        const [from, to] = filter.value;
        return (
          (from === null || number >= from) && (to === null || number <= to)
        );
      }
      if (filter.operator === "gt") return number > filter.value;
      if (filter.operator === "gte") return number >= filter.value;
      if (filter.operator === "lt") return number < filter.value;
      return number <= filter.value;
    }
  }
}

export function filterDataRows<T>(
  rows: readonly T[],
  filters: ColumnFiltersState,
  getValue: (row: T, columnId: string) => unknown,
): T[] {
  return rows.filter((row) =>
    filters.every((filter) =>
      matchesDataFilter(getValue(row, filter.id), filter.value),
    ),
  );
}

import type { ProductImage } from "@/lib/commerce";

export const MAX_PRODUCT_IMAGES = 6;
export const MAX_PRODUCT_IMAGE_BYTES = 8 * 1024 * 1024;
export const MAX_PRODUCT_IMAGE_EDGE = 900;
export const MAX_PRODUCT_IMAGE_SOURCE_CHARS = 1_000_000;
export const PRODUCT_IMAGE_ACCEPT = "image/png,image/jpeg,image/webp";
const TARGET_SOURCE_CHARS = 220_000;
const MAX_DECODED_EDGE = 8192;
const MAX_DECODED_PIXELS = 24_000_000;

export type ProductImageErrorCode =
  | "unsupported"
  | "empty"
  | "too-large"
  | "signature"
  | "dimensions"
  | "decode"
  | "encode"
  | "unsafe-source"
  | "aborted";

export class ProductImageError extends Error {
  readonly code: ProductImageErrorCode;

  constructor(code: ProductImageErrorCode) {
    super(code);
    this.name = "ProductImageError";
    this.code = code;
  }
}

export type ProductCropAspect =
  "original" | "square" | "portrait" | "landscape";
export type ProductCropSettings = {
  aspect: ProductCropAspect;
  zoom: number;
  rotation: 0 | 90 | 180 | 270;
  offsetX: number;
  offsetY: number;
};

export const defaultProductCrop: ProductCropSettings = {
  aspect: "original",
  zoom: 1,
  rotation: 0,
  offsetX: 0,
  offsetY: 0,
};

export function validateProductImageFile(file: Pick<File, "size" | "type">) {
  if (!["image/png", "image/jpeg", "image/webp"].includes(file.type))
    throw new ProductImageError("unsupported");
  if (!Number.isFinite(file.size) || file.size <= 0)
    throw new ProductImageError("empty");
  if (file.size > MAX_PRODUCT_IMAGE_BYTES)
    throw new ProductImageError("too-large");
}

/** Check the actual container as well as the browser-supplied MIME type. */
export function hasProductRasterSignature(bytes: Uint8Array, mime: string) {
  if (mime === "image/png") {
    return [137, 80, 78, 71, 13, 10, 26, 10].every(
      (byte, index) => bytes[index] === byte,
    );
  }
  if (mime === "image/jpeg")
    return bytes[0] === 255 && bytes[1] === 216 && bytes[2] === 255;
  if (mime === "image/webp") {
    return (
      bytes.length >= 12 &&
      [82, 73, 70, 70].every((byte, index) => bytes[index] === byte) &&
      [87, 69, 66, 80].every((byte, index) => bytes[index + 8] === byte)
    );
  }
  return false;
}

export function validateProductRasterDimensions(width: number, height: number) {
  if (
    !Number.isInteger(width) ||
    !Number.isInteger(height) ||
    width < 1 ||
    height < 1 ||
    width > MAX_DECODED_EDGE ||
    height > MAX_DECODED_EDGE ||
    width * height > MAX_DECODED_PIXELS
  ) {
    throw new ProductImageError("dimensions");
  }
}

export function fitProductRaster(
  width: number,
  height: number,
  maxEdge = MAX_PRODUCT_IMAGE_EDGE,
) {
  if (
    !Number.isFinite(width) ||
    !Number.isFinite(height) ||
    width <= 0 ||
    height <= 0 ||
    !Number.isFinite(maxEdge) ||
    maxEdge < 1
  ) {
    throw new ProductImageError("dimensions");
  }
  const edge = Math.min(MAX_PRODUCT_IMAGE_EDGE, Math.floor(maxEdge));
  const scale = Math.min(1, edge / Math.max(width, height));
  return {
    width: Math.max(1, Math.round(width * scale)),
    height: Math.max(1, Math.round(height * scale)),
  };
}

const clamp = (value: number, min: number, max: number, fallback: number) =>
  Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback;

/** Coordinates are in the rotated source, before output downsampling. */
export function getProductCropGeometry(
  width: number,
  height: number,
  settings: ProductCropSettings,
  maxEdge = MAX_PRODUCT_IMAGE_EDGE,
) {
  validateProductRasterDimensions(width, height);
  const rotation = [0, 90, 180, 270].includes(settings.rotation)
    ? settings.rotation
    : 0;
  const sideways = rotation === 90 || rotation === 270;
  const rotatedWidth = sideways ? height : width;
  const rotatedHeight = sideways ? width : height;
  const ratio =
    settings.aspect === "square"
      ? 1
      : settings.aspect === "portrait"
        ? 4 / 5
        : settings.aspect === "landscape"
          ? 4 / 3
          : rotatedWidth / rotatedHeight;
  const zoom = clamp(settings.zoom, 1, 3, 1);
  const cropWidth = Math.min(rotatedWidth, rotatedHeight * ratio) / zoom;
  const cropHeight = Math.min(rotatedHeight, rotatedWidth / ratio) / zoom;
  const x =
    ((rotatedWidth - cropWidth) * (clamp(settings.offsetX, -1, 1, 0) + 1)) / 2;
  const y =
    ((rotatedHeight - cropHeight) * (clamp(settings.offsetY, -1, 1, 0) + 1)) /
    2;
  return {
    rotation,
    rotatedWidth,
    rotatedHeight,
    x,
    y,
    cropWidth,
    cropHeight,
    ...fitProductRaster(cropWidth, cropHeight, maxEdge),
  };
}

/** Only prepared local rasters enter a canvas; remote and SVG sources never do. */
export function isEditableProductRaster(src: string) {
  return (
    src.length <= MAX_PRODUCT_IMAGE_SOURCE_CHARS &&
    /^data:image\/(?:png|jpeg|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(src)
  );
}

const builtInCropSources: Readonly<Record<string, string>> = Object.fromEntries(
  [
    "forma-desk-lamp",
    "arc-lounge-chair",
    "linea-notebook",
    "studio-tote",
    "morrow-ceramic-cup",
    "silhouette-vase",
    "fold-side-table",
    "essential-wall-print",
  ].flatMap((slug) => [
    [`/assets/products/${slug}.svg`, `/assets/products/${slug}.webp`],
    [`/assets/products/${slug}.webp`, `/assets/products/${slug}.webp`],
  ]),
);

/** Known demo wrappers crop their original local WebP, never the SVG itself. */
export function canCropProductImage(src: string) {
  return isEditableProductRaster(src) || Object.hasOwn(builtInCropSources, src);
}

export function productImageCropSource(
  src: string,
  assetPath: (path: string) => string,
) {
  if (isEditableProductRaster(src)) return src;
  if (Object.hasOwn(builtInCropSources, src)) {
    return assetPath(builtInCropSources[src]);
  }
  throw new ProductImageError("unsafe-source");
}

/** Read only the embedded raster; arbitrary SVG geometry is never decoded. */
export function extractProductRasterContainer(svg: string) {
  if (svg.length > MAX_PRODUCT_IMAGE_SOURCE_CHARS + 16_384) {
    throw new ProductImageError("too-large");
  }
  const images = [
    ...svg.matchAll(
      /<image\b[^>]*?\s(?:href|xlink:href)=["'](data:image\/(?:webp|png|jpeg);base64,[A-Za-z0-9+/]+={0,2})["'][^>]*>/g,
    ),
  ];
  if (images.length !== 1 || !isEditableProductRaster(images[0][1])) {
    throw new ProductImageError("unsafe-source");
  }
  return images[0][1];
}

export function productImageDisplaySource(
  src: string,
  assetPath: (path: string) => string,
) {
  return src.startsWith("/assets/") ? assetPath(src) : src;
}

export function reorderProductImages(
  images: readonly ProductImage[],
  id: string,
  destination: number,
): ProductImage[] {
  const result = [...images];
  const from = result.findIndex((image) => image.id === id);
  if (
    from < 0 ||
    !Number.isInteger(destination) ||
    destination < 0 ||
    destination >= result.length
  )
    return result;
  const [image] = result.splice(from, 1);
  result.splice(destination, 0, image);
  return result;
}

function checkAborted(signal?: AbortSignal) {
  if (signal?.aborted) throw new ProductImageError("aborted");
}

function loadLocalRaster(src: string, signal?: AbortSignal) {
  checkAborted(signal);
  return new Promise<HTMLImageElement>((resolve, reject) => {
    const image = new Image();
    let settled = false;
    const cleanup = () => {
      clearTimeout(timeout);
      image.onload = null;
      image.onerror = null;
      signal?.removeEventListener("abort", abort);
    };
    const fail = (error: ProductImageError) => {
      if (settled) return;
      settled = true;
      cleanup();
      image.src = "";
      reject(error);
    };
    const abort = () => fail(new ProductImageError("aborted"));
    const timeout = setTimeout(
      () => fail(new ProductImageError("decode")),
      15_000,
    );
    image.onload = () => {
      if (settled) return;
      try {
        validateProductRasterDimensions(
          image.naturalWidth,
          image.naturalHeight,
        );
        checkAborted(signal);
        settled = true;
        cleanup();
        resolve(image);
      } catch (cause) {
        fail(
          cause instanceof ProductImageError
            ? cause
            : new ProductImageError("decode"),
        );
      }
    };
    image.onerror = () => fail(new ProductImageError("decode"));
    image.decoding = "async";
    signal?.addEventListener("abort", abort, { once: true });
    image.src = src;
  });
}

export function decodeProductRaster(
  src: string,
  signal?: AbortSignal,
  assetPath: (path: string) => string = (path) => path,
) {
  // Text registry installs carry the embedded WebP inside the known SVG.
  // Extract it directly so cropping needs no unshipped binary companion.
  if (Object.hasOwn(builtInCropSources, src) && src.endsWith(".svg")) {
    return (async () => {
      checkAborted(signal);
      let response: Response;
      try {
        response = await fetch(assetPath(src), {
          signal,
          credentials: "same-origin",
          mode: "same-origin",
          redirect: "error",
          cache: "force-cache",
        });
      } catch {
        checkAborted(signal);
        throw new ProductImageError("decode");
      }
      if (!response.ok) throw new ProductImageError("decode");
      const source = extractProductRasterContainer(await response.text());
      checkAborted(signal);
      return loadLocalRaster(source, signal);
    })();
  }
  return loadLocalRaster(productImageCropSource(src, assetPath), signal);
}

export function drawProductRasterCrop(
  canvas: HTMLCanvasElement,
  image: HTMLImageElement,
  settings: ProductCropSettings,
  maxEdge = MAX_PRODUCT_IMAGE_EDGE,
) {
  const geometry = getProductCropGeometry(
    image.naturalWidth,
    image.naturalHeight,
    settings,
    maxEdge,
  );
  canvas.width = geometry.width;
  canvas.height = geometry.height;
  const context = canvas.getContext("2d");
  if (!context) throw new ProductImageError("encode");
  context.imageSmoothingEnabled = true;
  context.imageSmoothingQuality = "high";
  context.save();
  context.scale(
    geometry.width / geometry.cropWidth,
    geometry.height / geometry.cropHeight,
  );
  context.translate(-geometry.x, -geometry.y);
  context.translate(geometry.rotatedWidth / 2, geometry.rotatedHeight / 2);
  context.rotate((geometry.rotation * Math.PI) / 180);
  context.drawImage(image, -image.naturalWidth / 2, -image.naturalHeight / 2);
  context.restore();
  return geometry;
}

/** Prefer WebP, with the browser's PNG fallback; reduce size before storing. */
export function encodeProductRasterCrop(
  image: HTMLImageElement,
  settings: ProductCropSettings = defaultProductCrop,
): Pick<ProductImage, "src" | "width" | "height"> {
  const canvas = document.createElement("canvas");
  let smallest: Pick<ProductImage, "src" | "width" | "height"> | undefined;
  try {
    for (let pass = 0; pass < 7; pass++) {
      const edge = Math.max(
        180,
        Math.round(MAX_PRODUCT_IMAGE_EDGE * 0.78 ** pass),
      );
      drawProductRasterCrop(canvas, image, settings, edge);
      for (const quality of [0.82, 0.68, 0.54]) {
        const src = canvas.toDataURL("image/webp", quality);
        if (!isEditableProductRaster(src)) continue;
        const result = { src, width: canvas.width, height: canvas.height };
        if (!smallest || src.length < smallest.src.length) smallest = result;
        if (src.length <= TARGET_SOURCE_CHARS) return result;
      }
    }
    if (smallest) return smallest;
    throw new ProductImageError("encode");
  } catch (cause) {
    throw cause instanceof ProductImageError
      ? cause
      : new ProductImageError("encode");
  } finally {
    // Release the canvas backing store after an export, including on failure.
    canvas.width = 0;
    canvas.height = 0;
  }
}

export async function prepareProductImage(
  file: File,
  signal?: AbortSignal,
): Promise<Pick<ProductImage, "src" | "width" | "height">> {
  checkAborted(signal);
  validateProductImageFile(file);
  const signature = new Uint8Array(await file.slice(0, 16).arrayBuffer());
  checkAborted(signal);
  if (!hasProductRasterSignature(signature, file.type))
    throw new ProductImageError("signature");
  const url = URL.createObjectURL(file);
  try {
    const image = await loadLocalRaster(url, signal);
    checkAborted(signal);
    return encodeProductRasterCrop(image);
  } finally {
    URL.revokeObjectURL(url);
  }
}

/**
 * Add the build's mount point to a public asset or native HTML link.
 * Keep next/link and Next's router paths unprefixed: Next handles those itself.
 */
export function publicPath(
  path: string,
  basePath = process.env.NEXT_PUBLIC_BASE_PATH ?? "",
): string {
  if (!path.startsWith("/") || path.startsWith("//")) return path;
  const prefix = basePath.trim().replace(/^\/+|\/+$/g, "");
  if (!prefix) return path;
  const base = `/${prefix}`;
  if (
    path === base ||
    path.startsWith(`${base}/`) ||
    path.startsWith(`${base}?`) ||
    path.startsWith(`${base}#`)
  ) {
    return path;
  }
  return `${base}${path}`;
}

